package main

import (
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/gorilla/websocket"
	ldap "github.com/go-ldap/ldap/v3"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true // Allow all origins for internal service
	},
}

type LDAPConfig struct {
	Host     string
	Port     int
	BaseDN   string
	BindDN   string
	BindPass string
}

var ldapCfg = LDAPConfig{
	Host:     "ldap.internal.corp",
	Port:     389,
	BaseDN:   "dc=corp,dc=internal",
	BindDN:   "cn=svc-websocket,ou=services,dc=corp,dc=internal",
	BindPass: "svc-password-rotated",
}

func connectLDAP() (*ldap.Conn, error) {
	conn, err := ldap.Dial("tcp", fmt.Sprintf("%s:%d", ldapCfg.Host, ldapCfg.Port))
	if err != nil {
		return nil, err
	}
	err = conn.Bind(ldapCfg.BindDN, ldapCfg.BindPass)
	if err != nil {
		conn.Close()
		return nil, err
	}
	return conn, nil
}

// sanitizeInput performs basic sanitization but misses critical LDAP metacharacters
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Attempt to block obvious injection - but incomplete
	input = strings.ReplaceAll(input, ";", "")
	input = strings.ReplaceAll(input, "|", "")
	return input
}

func lookupUserPresence(username string) (string, error) {
	conn, err := connectLDAP()
	if err != nil {
		return "", fmt.Errorf("ldap connection failed: %w", err)
	}
	defer conn.Close()

	// VULNERABLE: username is interpolated directly into LDAP filter
	// sanitizeInput does NOT escape )(* and other LDAP filter metacharacters
	filter := fmt.Sprintf("(&(objectClass=person)(uid=%s))", sanitizeInput(username))

	searchReq := ldap.NewSearchRequest(
		ldapCfg.BaseDN,
		ldap.ScopeWholeSubtree,
		ldap.NeverDerefAliases,
		0, 0, false,
		filter,
		[]string{"uid", "cn", "mail", "employeeType", "memberOf"},
		nil,
	)

	result, err := conn.Search(searchReq)
	if err != nil {
		return "", fmt.Errorf("ldap search failed: %w", err)
	}

	if len(result.Entries) == 0 {
		return "offline", nil
	}

	entry := result.Entries[0]
	return fmt.Sprintf("online|%s|%s|%s",
		entry.GetAttributeValue("cn"),
		entry.GetAttributeValue("mail"),
		entry.GetAttributeValue("memberOf")), nil
}

func handlePresenceWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			if websocket.IsUnexpectedCloseError(err, websocket.CloseGoingAway) {
				log.Printf("ws error: %v", err)
			}
			break
		}

		username := string(message)
		log.Printf("presence lookup requested for: %s", username)

		status, err := lookupUserPresence(username)
		if err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte("error: "+err.Error()))
			continue
		}

		conn.WriteMessage(websocket.TextMessage, []byte(status))
	}
}

func main() {
	http.HandleFunc("/ws/presence", handlePresenceWS)
	log.Println("WebSocket presence service starting on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
